const s = wb.getWorksheet('Output');
log('before', s.getRange('B11:B17'));
const yes = (await wb.evaluate('=SUMPRODUCT(--(Input!E9:E33="yes"))'));
const exact = (await wb.evaluate('=SUMPRODUCT(--EXACT(Input!E9:E33,"yes"))'));
const lenOdd = (await wb.evaluate('=SUMPRODUCT(--(LEN(Input!E9:E33)<>LEN(TRIM(Input!E9:E33))))'));
log({yes, exact, lenOdd});
for (let r = 11; r <= 17; r++) {
  s.getRange(`B${r}`).setValue(`=INDEX(Input!$B$9:$B$33,AGGREGATE(15,6,(ROW(Input!$E$9:$E$33)-ROW(Input!$E$9)+1)/((Input!$E$9:$E$33="yes")*(Input!$B$9:$B$33<>"")),ROWS(B$11:B${r})))`);
}
const check = await wb.evaluate('=SUMPRODUCT(COUNTIFS(Input!B9:B33,Output!B11:B17,Input!E9:E33,"yes"))');
log('match count', check);
const out = [];
for (let r = 11; r <= 17; r++) { const c = s.getRange(`B${r}`); out.push([r, c.getFormulas()?.[0]?.[0], c.getValues()[0][0], c.getText?.()]); }
log(JSON.stringify(out));
s.getRange('A10:B18')

